import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: ChunkHolder<TChunk>","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ChunkHolder<TChunk>"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkHolder"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/ChunkHolder"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/chunkgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/ChunkHolder.md","filePath":"api/@jsprismarine/chunkgen/classes/ChunkHolder.md","lastUpdated":1794433523000}`),a={name:`api/@jsprismarine/chunkgen/classes/ChunkHolder.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/chunkgen</a> / ChunkHolder</p><h1 id="class-chunkholder-tchunk" tabindex="-1">Class: ChunkHolder&lt;TChunk&gt; <a class="header-anchor" href="#class-chunkholder-tchunk" aria-label="Permalink to “Class: ChunkHolder&lt;TChunk&gt;”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L80" target="_blank" rel="noreferrer">ChunkHolder.ts:80</a></p><p>One chunk&#39;s place in the ladder: the promise each status resolved to, and who still needs it.</p><p>This is Java&#39;s <code>GenerationChunkHolder</code>. Two mechanisms carry the whole design.</p><p>One promise per status, created by the first caller and awaited by every later one, is what makes a (chunk, status) body run exactly once however many requests overlap. Java needs a compare-and-exchange on <code>startedWork</code> because several pool threads reach <code>applyStep</code> at once; only the thread that owns the holder map touches a holder here, and a map insert cannot be interleaved, so the promise slot does the same job. <code>startedWork</code> is kept anyway, because it is what catches a layer loop that skips a rung.</p><p>A reference count, rather than a cache eviction policy, decides when the holder goes away. Every generation task that needs this chunk inside its radius acquires one and releases it when it finishes, and <code>ChunkHolderMap</code> drops the holder at zero. An LRU would evict a chunk a running feature pass is still writing into.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="tchunk" tabindex="-1">TChunk <a class="header-anchor" href="#tchunk" aria-label="Permalink to “TChunk”">​</a></h3><p><code>TChunk</code> <em>extends</em> <a href="./../#stagedchunk"><code>StagedChunk</code></a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ChunkHolder</strong>&lt;<code>TChunk</code>&gt;(<code>chunkX</code>, <code>chunkZ</code>, <code>newChunk</code>): <code>ChunkHolder</code>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L96" target="_blank" rel="noreferrer">ChunkHolder.ts:96</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><p>Chunk x coordinate.</p><h5 id="chunkz" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><p>Chunk z coordinate.</p><h5 id="newchunk" tabindex="-1">newChunk <a class="header-anchor" href="#newchunk" aria-label="Permalink to “newChunk”">​</a></h5><p>(<code>chunkX</code>, <code>chunkZ</code>) =&gt; <code>TChunk</code></p><p>Allocates the chunk the <code>empty</code> status starts from. It is called once, on the first step, so a holder that is acquired and never stepped costs nothing. A server that reads chunks from disk replaces this with the load.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ChunkHolder</code>&lt;<code>TChunk</code>&gt;</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="chunkx-1" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx-1" aria-label="Permalink to “chunkX”">​</a></h3><blockquote><p><code>readonly</code> <strong>chunkX</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L97" target="_blank" rel="noreferrer">ChunkHolder.ts:97</a></p><p>Chunk x coordinate.</p><hr><h3 id="chunkz-1" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz-1" aria-label="Permalink to “chunkZ”">​</a></h3><blockquote><p><code>readonly</code> <strong>chunkZ</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L98" target="_blank" rel="noreferrer">ChunkHolder.ts:98</a></p><p>Chunk z coordinate.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="referencecount" tabindex="-1">referenceCount <a class="header-anchor" href="#referencecount" aria-label="Permalink to “referenceCount”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>referenceCount</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L113" target="_blank" rel="noreferrer">ChunkHolder.ts:113</a></p><p>How many generation tasks still need this chunk.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><hr><h3 id="startedstatus" tabindex="-1">startedStatus <a class="header-anchor" href="#startedstatus" aria-label="Permalink to “startedStatus”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>startedStatus</strong>(): <code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L108" target="_blank" rel="noreferrer">ChunkHolder.ts:108</a></p><p>The highest status whose body has been started, which is at or above <a href="#status">status</a>.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code> | <code>undefined</code></p><hr><h3 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h3><h4 id="get-signature-2" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-2" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>status</strong>(): <code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L103" target="_blank" rel="noreferrer">ChunkHolder.ts:103</a></p><p>The highest status whose body has finished, or undefined before <code>empty</code> has run.</p><h5 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code> | <code>undefined</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="acquire" tabindex="-1">acquire() <a class="header-anchor" href="#acquire" aria-label="Permalink to “acquire()”">​</a></h3><blockquote><p><strong>acquire</strong>(): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L123" target="_blank" rel="noreferrer">ChunkHolder.ts:123</a></p><p>Records that one more task needs this chunk. Pairs with <a href="#release">release</a>.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>this</code></p><hr><h3 id="applystep" tabindex="-1">applyStep() <a class="header-anchor" href="#applystep" aria-label="Permalink to “applyStep()”">​</a></h3><blockquote><p><strong>applyStep</strong>(<code>step</code>, <code>body</code>): <code>Promise</code>&lt;<code>TChunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L179" target="_blank" rel="noreferrer">ChunkHolder.ts:179</a></p><p>Runs a step on this chunk, or joins the run that is already under way.</p><p>Java&#39;s <code>GenerationChunkHolder.applyStep</code>. The first caller for a status creates the promise and <code>body</code> runs once; every later caller gets that same promise back and <code>body</code> is not called again. The run waits for the parent status&#39;s promise first, so two statuses of one chunk are never in flight together.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="step" tabindex="-1">step <a class="header-anchor" href="#step" aria-label="Permalink to “step”">​</a></h5><p><a href="./ChunkStep.html"><code>ChunkStep</code></a></p><p>The rung to climb, which also carries the window the body may read.</p><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to “body”">​</a></h5><p><a href="./../#chunkstepbody"><code>ChunkStepBody</code></a>&lt;<code>TChunk</code>&gt;</p><p>What to run, supplied by the caller because the status bodies live outside this package.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>TChunk</code>&gt;</p><p>The chunk at <code>step.targetStatus</code>.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>ChunkStepOutOfOrderError when the holder has not started the parent status.</p><hr><h3 id="chunkat" tabindex="-1">chunkAt() <a class="header-anchor" href="#chunkat" aria-label="Permalink to “chunkAt()”">​</a></h3><blockquote><p><strong>chunkAt</strong>(<code>status</code>): <code>TChunk</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L158" target="_blank" rel="noreferrer">ChunkHolder.ts:158</a></p><p>The chunk, having checked that it has reached the status the reader needs.</p><p>The chunk returned is the live one, so it may be at a status above <code>status</code> when another task has already driven it further. That is Java&#39;s behavior too: <code>WorldGenRegion.getChunk</code> checks the guarantee and then hands over the live <code>ChunkAccess</code>. It is also why <code>features</code> records its neighbor writes as a patch rather than applying them, which is slice 7.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-1" tabindex="-1">status <a class="header-anchor" href="#status-1" aria-label="Permalink to “status”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>TChunk</code></p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>ChunkNotReadyError when the chunk has not reached that status.</p><hr><h3 id="futurefor" tabindex="-1">futureFor() <a class="header-anchor" href="#futurefor" aria-label="Permalink to “futureFor()”">​</a></h3><blockquote><p><strong>futureFor</strong>(<code>status</code>): <code>Promise</code>&lt;<code>TChunk</code>&gt; | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L144" target="_blank" rel="noreferrer">ChunkHolder.ts:144</a></p><p>The promise a status resolved or will resolve to, or undefined when it has not been asked for.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-2" tabindex="-1">status <a class="header-anchor" href="#status-2" aria-label="Permalink to “status”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>TChunk</code>&gt; | <code>undefined</code></p><hr><h3 id="hasreached" tabindex="-1">hasReached() <a class="header-anchor" href="#hasreached" aria-label="Permalink to “hasReached()”">​</a></h3><blockquote><p><strong>hasReached</strong>(<code>status</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L118" target="_blank" rel="noreferrer">ChunkHolder.ts:118</a></p><p>Whether the chunk&#39;s body for <code>status</code> has finished.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status-3" tabindex="-1">status <a class="header-anchor" href="#status-3" aria-label="Permalink to “status”">​</a></h5><p><code>&quot;empty&quot;</code> | <code>&quot;structure_starts&quot;</code> | <code>&quot;structure_references&quot;</code> | <code>&quot;biomes&quot;</code> | <code>&quot;terrain&quot;</code> | <code>&quot;features&quot;</code> | <code>&quot;initialize_light&quot;</code> | <code>&quot;light&quot;</code> | <code>&quot;spawn&quot;</code> | <code>&quot;full&quot;</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="release" tabindex="-1">release() <a class="header-anchor" href="#release" aria-label="Permalink to “release()”">​</a></h3><blockquote><p><strong>release</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/chunkgen/src/ChunkHolder.ts#L135" target="_blank" rel="noreferrer">ChunkHolder.ts:135</a></p><p>Records that one task no longer needs this chunk.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The remaining count. At zero the holder is finished with and its map drops it.</p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>RangeError when the holder is already unreferenced, which means a task released twice and some other task&#39;s holder is about to be dropped out from under it.</p>`,128)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};